#pragma once

// A print host's own web page -- Mainsail, Fluidd, OctoPrint, PrusaLink -- in
// a window of its own, opened from the printer's card on Home.
//
// The content is Orca's Device tab view, PrinterWebView, unchanged. Orca
// loads that tab from the *selected* printer, so showing it for another
// printer would switch the open project's printer. Here it is loaded from the
// printer's own saved address instead, and nothing about the project or the
// page the person is on changes.

#include "PopOutWindow.hpp"

#include <string>

namespace Slic3r {
class DynamicPrintConfig;
namespace GUI {
class PrinterWebView;
}
} // namespace Slic3r

namespace Slic3r { namespace GUI { namespace JusPrin { namespace Home {

class PrinterWindow final : public PopOutWindow
{
public:
    // `config` is the printer's own profile, whose print host is loaded.
    PrinterWindow(const std::string& printer_name, const DynamicPrintConfig& config);

    PrinterWebView* view() const { return m_view; }

    // The page `config` names for its print host, as Orca's Device tab
    // computes it; empty when the profile has no print host.
    static std::string page_url(const DynamicPrintConfig& config);

private:
    PrinterWebView* m_view{nullptr};
};

}}}} // namespace Slic3r::GUI::JusPrin::Home
#include "PrinterWindow.hpp"

#include "slic3r/GUI/PrinterWebView.hpp"
#include "slic3r/Utils/PrintHost.hpp"
#include "libslic3r/PrintConfig.hpp"

namespace Slic3r { namespace GUI { namespace JusPrin { namespace Home {

namespace {

// PrusaLink and PrusaConnect pages sign in with the saved API key, as
// MainFrame::load_printer_url passes it to the Device tab.
wxString page_api_key(const DynamicPrintConfig& config)
{
    const auto* type = config.option<ConfigOptionEnum<PrintHostType>>("host_type");
    if (type == nullptr || !config.has("printhost_apikey") || (type->value != htPrusaLink && type->value != htPrusaConnect))
        return {};
    return wxString::FromUTF8(config.opt_string("printhost_apikey"));
}

} // namespace

std::string PrinterWindow::page_url(const DynamicPrintConfig& config)
{
    // get_print_host_webui takes a mutable config; it only reads it.
    DynamicPrintConfig copy = config;
    return PrintHost::get_print_host_webui(&copy);
}

PrinterWindow::PrinterWindow(const std::string& printer_name, const DynamicPrintConfig& config)
    : PopOutWindow(wxString::FromUTF8(printer_name))
{
    m_view = new PrinterWebView(this);
    set_content(m_view);
    Show();
    // PrinterWebView defers a load until it is shown, so the load follows Show.
    wxString url = wxString::FromUTF8(page_url(config));
    m_view->load_url(url, page_api_key(config));
}

}}}} // namespace Slic3r::GUI::JusPrin::Home
#pragma once

// A printer's window of its own, beside the app rather than inside it: the
// person can move it, minimise it and keep it in view while working in a
// project. It has no parent, so it has its own taskbar entry; whoever opens
// one closes it when the app's main window goes.
//
// The content is one of Orca's own views, and every such view holds a web
// view, so the window owns the one safe way to destroy it (see release()).

#include <wx/frame.h>
#include <wx/timer.h>

namespace Slic3r { namespace GUI { namespace JusPrin { namespace Home {

class PopOutWindow : public wxFrame
{
public:
    // Destroys the window, or hides it and destroys it once no web view is
    // installing its script handler (see release()). The title bar's close
    // comes here too.
    void close();
    bool closing() const { return m_closing; }

    // Back in front of the person, out of the Dock if it was minimised.
    void bring_forward();

protected:
    explicit PopOutWindow(const wxString& title);

    // Fills the window with `content`, which must be a child of this window,
    // and sizes and centres it. Called once, before Show().
    void set_content(wxWindow* content);

private:
    void release();

    wxWindow* m_content{nullptr};
    wxTimer   m_release_timer;
    bool      m_closing{false};
};

}}}} // namespace Slic3r::GUI::JusPrin::Home
#include "PopOutWindow.hpp"

#include "slic3r/GUI/GUI_App.hpp"
#include "slic3r/GUI/MainFrame.hpp"

#include <wx/sizer.h>

namespace Slic3r { namespace GUI { namespace JusPrin { namespace Home {

namespace {

// How long to wait before trying again to destroy a closed window whose
// release had to wait for a web view's script handler install.
constexpr int kReleaseRetryMs = 50;

} // namespace

PopOutWindow::PopOutWindow(const wxString& title)
    : wxFrame(nullptr, wxID_ANY, title)
    , m_release_timer(this)
{
    if (MainFrame* frame = wxGetApp().mainframe)
        SetIcons(frame->GetIcons());
    Bind(wxEVT_CLOSE_WINDOW, [this](wxCloseEvent&) { close(); });
    Bind(wxEVT_TIMER, [this](wxTimerEvent&) { release(); }, m_release_timer.GetId());
}

void PopOutWindow::set_content(wxWindow* content)
{
    m_content   = content;
    auto* sizer = new wxBoxSizer(wxVERTICAL);
    sizer->Add(content, wxSizerFlags(1).Expand());
    SetSizer(sizer);
    SetSize(FromDIP(wxSize(1200, 800)));
    CentreOnScreen();
    // The title bar follows the app's appearance, as Orca's own frames do.
    wxGetApp().UpdateFrameDarkUI(this);
}

void PopOutWindow::bring_forward()
{
    Iconize(false);
    Raise();
}

void PopOutWindow::close()
{
    if (m_closing)
        return;
    m_closing = true;
    release();
}

// On macOS a new web view installs its script message handler from a
// CallAfter (WebView::CreateWebView), and wx waits for WebKit's reply to that
// install inside a nested event loop, with the app's
// is_adding_script_handler() flag set until it returns. A view destroyed
// during that wait is called back by WebKit after it is gone, and the app
// crashes. wx's own Destroy() of a frame only queues it for the next idle,
// and that idle can come inside the very install the view queued at creation,
// so the content is deleted here, synchronously, at a moment no install is
// running: deleting it also drops an install it has queued but not started.
// The frame, with no web view left in it, then goes the usual way.
void PopOutWindow::release()
{
    if (wxGetApp().is_adding_script_handler()) {
        Hide();
        m_release_timer.StartOnce(kReleaseRetryMs);
        return;
    }
    if (m_content != nullptr) {
        m_content->Destroy();
        m_content = nullptr;
    }
    Destroy();
}

}}}} // namespace Slic3r::GUI::JusPrin::Home
