// A Bambu Lab printer's monitor -- camera, progress, temperatures, controls,
// storage, firmware and the assistant -- in a window of its own, opened from
// the printer's card on Home or from the header's printer menu.
//
// The content is Orca's own Device page, MonitorPanel, as a second instance.
// The one inside the main window is a Notebook page whose content follows
// the *selected* printer profile (a print host's page when that profile is
// not a Bambu Lab printer), so jumping to it from a card showed another
// printer's page. This window always holds the monitor.
//
// Orca has one selected machine and one printer agent at a time, and the
// monitor shows that machine. So there is one monitor window: showing a
// printer selects it, as choosing it in Orca's own device list does, and the
// window says which printer it is showing. While the project's printer is
// not a Bambu Lab printer, Orca talks to no Bambu Lab printer at all, and the
// monitor says so in its own words.

#include "PopOutWindow.hpp"

#include <wx/timer.h>

#include <string>

namespace Slic3r { namespace GUI {
class MonitorPanel;
}} // namespace Slic3r::GUI

namespace Slic3r { namespace GUI { namespace JusPrin { namespace Home {

class MonitorWindow final : public PopOutWindow
{
public:
    MonitorWindow();

    // Shows the device `device_id` and brings the window forward.
    void show_printer(const std::string& device_id);

    MonitorPanel* panel() const { return m_panel; }

private:
    // The title names the machine the monitor shows, which Orca's own device
    // list inside the window can change.
    void update_title();

    MonitorPanel* m_panel{nullptr};
    wxTimer       m_title_timer;
    std::string   m_titled_device;
};

}}}} // namespace Slic3r::GUI::JusPrin::Home
#include "MonitorWindow.hpp"

#include "slic3r/GUI/DeviceCore/DevManager.h"
#include "slic3r/GUI/DeviceManager.hpp"
#include "slic3r/GUI/GUI_App.hpp"
#include "slic3r/GUI/JusPrin/Printers/NamedPrinters.hpp"
#include "slic3r/GUI/Monitor.hpp"

#include <wx/display.h>

#include <algorithm>

namespace Slic3r { namespace GUI { namespace JusPrin { namespace Home {

namespace {

constexpr int kTitleRefreshMs = 1000;

MachineObject* selected_machine()
{
    DeviceManager* devices = wxGetApp().getDeviceManager();
    return devices != nullptr ? devices->get_selected_machine() : nullptr;
}

} // namespace

MonitorWindow::MonitorWindow()
    : PopOutWindow(wxString())
    , m_title_timer(this)
{
    m_panel = new MonitorPanel(this, wxID_ANY);
    set_content(m_panel);
    // The monitor's columns need more width than a web page does; without it
    // the controls sit behind a horizontal scroll bar. Fit them, within the
    // screen.
    const wxRect screen = wxDisplay(this).GetClientArea();
    SetSize(wxSize(std::min(std::max(GetSize().x, GetBestSize().x), screen.width),
                   std::min(std::max(GetSize().y, GetBestSize().y), screen.height)));
    CentreOnScreen();
    Show();
    // A Notebook shows its page through the page's own Show(), which is
    // where MonitorPanel starts reading the machine; a frame does not, so
    // the window does it.
    m_panel->Show(true);
    Bind(wxEVT_TIMER, [this](wxTimerEvent&) { update_title(); }, m_title_timer.GetId());
    m_title_timer.Start(kTitleRefreshMs);
}

void MonitorWindow::show_printer(const std::string& device_id)
{
    // Upstream reconnects a LAN printer that is selected again, dropping its
    // connection for nothing, so a printer already shown is left as it is.
    // Otherwise the monitor's own selection, as its device list makes it.
    if (const MachineObject* shown = selected_machine(); shown == nullptr || shown->get_dev_id() != device_id)
        m_panel->select_machine(device_id);
    // The selection is queued, so the title follows it rather than now.
    CallAfter([this] { update_title(); });
    bring_forward();
}

void MonitorWindow::update_title()
{
    const MachineObject* shown = selected_machine();
    if (shown == nullptr || shown->get_dev_id() == m_titled_device)
        return;
    m_titled_device = shown->get_dev_id();
    // The name the person gave the printer, or the machine's own.
    wxString title = wxString::FromUTF8(shown->get_dev_name());
    for (const Printers::NamedPrinter& named : Printers::named_printers())
        if (named.device_id == m_titled_device)
            title = wxString::FromUTF8(named.name);
    SetTitle(title);
}

}}}} // namespace Slic3r::GUI::JusPrin::Home
