        *detail = said.ToUTF8().data();
        verdict->store(passed ? HostVerdict::Passed : HostVerdict::Failed);
    }).detach();
    m_host_attempt = HostAttempt{name, host_type, address, key, std::chrono::steady_clock::now(), std::move(verdict), std::move(detail),
